<?php
namespace Tests\Feature\Academic;
use App\Modules\Academic\Models\{AcademicLevel,AcademicProgram,AcademicYear,CampaignHospital,Promotion,Student};use App\Modules\Auth\Models\User;use App\Modules\Institution\Models\Institution;use App\Shared\Enums\InstitutionRole;use Database\Seeders\AcademicLevelSeeder;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class D4CampaignReservationTest extends TestCase{use RefreshDatabase;
 public function test_hospital_capacity_cannot_be_exceeded_by_student_reservations():void{$this->seed(AcademicLevelSeeder::class);$university=Institution::factory()->create(['type'=>'UNIVERSITY']);$hospital=Institution::factory()->create(['type'=>'HOSPITAL']);$academicManager=User::factory()->create();$hospitalManager=User::factory()->create();$this->assignInstitutionRole($academicManager,$university,InstitutionRole::AcademicManager->value);$this->assignInstitutionRole($hospitalManager,$hospital,InstitutionRole::HospitalManager->value);$year=AcademicYear::create(['label'=>'2026-2027','starts_on'=>'2026-09-01','ends_on'=>'2027-08-31','status'=>'CURRENT','is_current'=>true]);$program=AcademicProgram::create(['university_id'=>$university->id,'code'=>'MED','name'=>'Médecine','status'=>'ACTIVE']);$level=AcademicLevel::where('code','D4')->firstOrFail();$promotion=Promotion::create(['program_id'=>$program->id,'level_id'=>$level->id,'academic_year_reference_id'=>$year->id,'academic_year_id'=>null,'name'=>'D4 Médecine','status'=>'ACTIVE']);
 $campaignId=$this->actingAs($academicManager)->postJson('/api/v1/academic/campaigns',['university_id'=>$university->public_id,'academic_year_id'=>$year->id,'name'=>'Stage D4','strategy'=>'D4_RESERVATION','instructions'=>'Choisir un hôpital.','starts_at'=>now()->addWeek(),'ends_at'=>now()->addMonths(3),'promotion_ids'=>[$promotion->id],'hospital_ids'=>[$hospital->public_id]])->assertCreated()->json('data.id');$this->patchJson("/api/v1/academic/campaigns/{$campaignId}/status",['status'=>'OPEN'])->assertOk();$requestId=CampaignHospital::where('campaign_id',$campaignId)->value('id');$this->actingAs($hospitalManager)->patchJson("/api/v1/academic/campaign-requests/{$requestId}/respond",['decision'=>'ACCEPTED','capacity'=>1])->assertOk();
 $first=User::factory()->create();$second=User::factory()->create();foreach([$first,$second]as$user){$student=Student::factory()->create(['user_id'=>$user->id,'university_id'=>$university->id]);$student->enrollments()->create(['promotion_id'=>$promotion->id,'status'=>'ACTIVE','enrolled_at'=>now()]);}$this->actingAs($first)->postJson("/api/v1/academic/campaigns/{$campaignId}/reserve",['hospital_id'=>$hospital->public_id])->assertCreated();$this->actingAs($second)->postJson("/api/v1/academic/campaigns/{$campaignId}/reserve",['hospital_id'=>$hospital->public_id])->assertUnprocessable();$this->assertDatabaseHas('capacity_pools',['total_places'=>1,'reserved_places'=>1]);}
}
